import{_ as o,l as i,o as e,c as d,v as r,p as s,x as l,d as n,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"Merkle–Damgård","description":"","frontmatter":{"title":"Merkle–Damgård","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/merkle-damgard.md","filePath":"cs/merkle-damgard.md","lastUpdated":1789023840000}'),c={name:"cs/merkle-damgard.md"};function p(_,a,D,u,A,k){const t=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="merkle–damgard" tabindex="-1">Merkle–Damgård <a class="header-anchor" href="#merkle–damgard" aria-label="Permalink to &quot;Merkle–Damgård&quot;">​</a></h1><div class="epigraph"><p>把固定长压缩函数迭代起来，吃掉任意长消息：Merkle–Damgård 给 MD5、SHA-1、SHA-2 这族骨架。碰撞安全可从压缩函数归约，但也带上长度扩展这份遗产。</p><footer>—— Merkle, 1979；Damgård, A Design Principle for Hash Functions, CRYPTO 1989</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/padding-oracle">填充预言</a>关掉解密错误通道。密码学哈希在主干<a href="/cs/hash-collision">哈希与碰撞</a>已有三条性质。缺口是<strong>构造</strong>：压缩函数如何接成长消息哈希，以及填充规则为何变成后课 HMAC 的理由。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>压缩函数 \\(h:\\{0,1\\}^{n+b}\\to\\{0,1\\}^n\\) 只吃一块。MD：把消息分块，链上链接值 \\(IV\\)，最后一块含长度。若 \\(h\\) 抗碰撞，则迭代后的 \\(H\\) 也抗碰撞（在填充得当时）。缺口是这条归约，以及链上状态泄漏带来的长度扩展——不是再定义原像。</p><h3 id="md5-sha-1-已不当碰撞哈希" tabindex="-1">MD5/SHA-1 已不当碰撞哈希 <a class="header-anchor" href="#md5-sha-1-已不当碰撞哈希" aria-label="Permalink to &quot;MD5/SHA-1 已不当碰撞哈希&quot;">​</a></h3><p>骨架仍值得学，因为 SHA-2 还在用它。碰撞已被找到的算法只当反例。</p><p><span class="marginnote">Damgård CRYPTO 1989。长度填充是归约的一部分：不同长度不能默默撞进同一链。本课不给碰撞搜索程序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 IV → 压缩 → 压缩 → 输出。写长度填充的动机。指出 SHA-256 仍是 MD；SHA-3 不是。下一课海绵。</p>',12)),(e(),s(m,null,{default:l(()=>[h(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20IV%5B%22IV%22%5D%20--%3E%20C1%5B%22%E5%8E%8B%E7%BC%A9%20h%22%5D%0A%20%20M1%5B%22%E5%9D%97%201%22%5D%20--%3E%20C1%0A%20%20C1%20--%3E%20C2%5B%22%E5%8E%8B%E7%BC%A9%20h%22%5D%0A%20%20M2%5B%22%E5%9D%97%202%22%5D%20--%3E%20C2%0A%20%20C2%20--%3E%20OUT%5B%22%E6%91%98%E8%A6%81%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>签名与承诺吃的是 \\(H(m)\\)。MD 让 \\(H\\) 可流式更新。链上链接值等于「内部状态」；若敌手知道 \\(H(m)\\) 且 \\(H\\) 是裸 MD，状态可被继续压缩——这是长度扩展，下一课用 HMAC 关。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证全部填充变体，不把 Keccak 提前讲完。海绵结构下一课换掉「链上状态即摘要」这一条。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主动加密预言之后，回到哈希骨架。</li><li>MD：压缩函数迭代 + 长度填充。</li><li>碰撞归约成立，长度扩展是遗产。</li><li>SHA-3 海绵是下一种结构。</li><li>出处：Merkle；Damgård, 1989；对照 NIST SHA-2。</li></ul>',8))])}const M=o(c,[["render",p]]);export{g as __pageData,M as default};
